def min_coins_greedy(amount, denominations):
    coins = 0
    i = len(denominations) - 1
    while amount > 0:
        while i >= 0 and denominations[i] > amount:
            i -= 1
        if i < 0:
            break
        amount -= denominations[i]
        coins += 1
    return coins

def min_coins_optimal(amount, denominations, memo={}):
    if amount in memo:
        return memo[amount]
    if amount == 0:
        return 0
    min_coins = float('inf')
    for coin in denominations:
        if amount >= coin:
            min_coins = min(min_coins, 1 + min_coins_optimal(amount - coin, denominations, memo))
    memo[amount] = min_coins
    return min_coins

def is_canonical(denominations):
    n = len(denominations)
    sum_of_two_largest = denominations[-1] + denominations[-2]
    for x in range(1, sum_of_two_largest):
        if min_coins_greedy(x, denominations) > min_coins_optimal(x, denominations):
